package com.mcnex.conversation;
final class MinutesDocument {
 static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String html(String title,String metadata,String raw){StringBuilder out=new StringBuilder("<!doctype html><html lang='ko'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>").append(escape(title)).append("</title><style>");out.append("@page{size:A4;margin:18mm 16mm}*{box-sizing:border-box}body{margin:0;background:#e9ede9;color:#19382f;font:15px/1.8 sans-serif}.paper{max-width:800px;margin:24px auto;padding:52px 46px;background:white;box-shadow:0 8px 32px #19382f14}.eyebrow{font-size:11px;letter-spacing:3px;color:#6c8075;font-weight:bold}h1{font-size:30px;line-height:1.35;letter-spacing:-1px;margin:14px 0 18px}.rule{height:5px;background:#19382f;margin:24px 0}.meta{border-top:1px solid #cdd8cf;border-bottom:1px solid #cdd8cf;padding:12px 0;font-size:12px;color:#526c5d;white-space:pre-line}h2{font-size:19px;margin:28px 0 12px;border-bottom:1px solid #cedacf;padding-bottom:8px;break-after:avoid}h2 svg{width:20px;height:20px;vertical-align:-4px;margin-right:9px;color:#48633e}.num{font-size:12px;color:#829474;margin-right:12px}.summary{background:#f0f5e9;padding:1px 18px 14px;margin-top:24px;border-left:4px solid #a5bf78}.summary h2{border:0}p{margin:7px 0;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;margin:14px 0;font-size:13px}th{background:#19382f;color:white;text-align:left}th,td{padding:10px;border:1px solid #cdd8cf;vertical-align:top;overflow-wrap:anywhere}tr{break-inside:avoid}tr:nth-child(even){background:#f6f8f4}.note{font-size:11px;color:#738274;border-top:1px solid #cedacf;margin-top:36px;padding-top:12px}.section{break-inside:auto}.section h2{break-after:avoid}@media(max-width:600px){.paper{margin:0;padding:28px 22px;box-shadow:none}h1{font-size:25px}}@media print{body{background:white;font-size:11pt}.paper{max-width:none;margin:0;padding:0;box-shadow:none}h1{font-size:23pt}h2{font-size:14pt}thead{display:table-header-group}.summary{print-color-adjust:exact}th{print-color-adjust:exact}}");out.append("</style></head><body><article class='paper'><div class='eyebrow'>MEMO / MEETING MINUTES</div><h1>").append(escape(title)).append("</h1><div class='meta'>").append(escape(metadata)).append("</div><div class='rule'></div>");int number=0;for(MinutesCards.Section section:MinutesCards.parse(raw)){if(section.lines.isEmpty())continue;number++;boolean summary=MinutesCards.icon(section.title).equals("summary");out.append("<section class='").append(summary?"summary":"section").append("'><h2><span class='num'>").append(String.format(java.util.Locale.ROOT,"%02d",number)).append("</span>").append(DocumentIcons.svg(MinutesCards.icon(section.title))).append(escape(section.title)).append("</h2>");boolean table=false;for(String line:section.lines){String[] cells=line.replaceAll("^\\|+|\\|+$","").split("\\|",-1);boolean task=(section.title.contains("과제")||section.title.contains("할 일"))&&cells.length==3;if(task){if(line.matches("[ :|−-]+"))continue;if(!table){out.append("<table><thead><tr><th>실행 과제</th><th>담당자</th><th>기한</th></tr></thead><tbody>");table=true;}if(cells[0].trim().matches("할 일|실행 과제|업무"))continue;out.append("<tr>");for(String cell:cells)out.append("<td>").append(escape(cell.trim().isEmpty()?"미정":cell.trim())).append("</td>");out.append("</tr>");}else{if(table){out.append("</tbody></table>");table=false;}out.append("<p>").append(escape(line.replaceFirst("^[-*]\\s+","• "))).append("</p>");}}if(table)out.append("</tbody></table>");out.append("</section>");}return out.append("<footer class='note'>AI가 정리한 회의록입니다. 결정 사항·담당자·기한은 자막 원문과 함께 확인하세요.<br>MEMO · 회의 기록</footer></article></body></html>").toString();}
}
